"""Weeks 6+ questions use only the revised taught pandas workflow.
The answer positions are shuffled per cohort by the existing generator.
"""
def question(stem,pre,correct,reason,wrong,kind='interpretation'):
 return dict(stem=stem,pre=pre,kind=kind,options=[(correct,True,reason)]+[(text,False,feedback) for text,feedback in wrong])

def apply(quiz):
 q=question
 banks={
 6:[
 q('Which entry does the missing-value check identify?','s = pd.Series([0, None, 4])\nprint(s.isna().tolist())','Only the middle entry','Zero is a recorded number. isna recognises the missing middle entry.', [('Zero and the middle entry','Zero is not automatically missing.'),('Every entry','The first and last entries are recorded numbers.'),('No entries','pandas recognises the missing marker even if the numeric Series stores it as NaN.')]),
 q('What is wrong with this duplicate rule?','Rows are separate observations. Equipment E1 has several valid readings.\nclean = df.drop_duplicates("equipment_id")','It removes distinct observations from the same equipment','Deduplicate observation IDs under the stated policy. A source ID can repeat.', [('It keeps every observation','It retains only the first row per equipment ID.'),('It fills missing values','drop_duplicates does not fill missing fields.'),('It sorts by target','This operation removes rows; it does not sort targets.')],'diagnosis'),
 q('Why does this conversion fail?','pd.to_numeric(pd.Series(["20", "24 C", "26"]))\nValueError: Unable to parse string "24 C" at position 1','The second value contains a unit suffix','The value and its position identify what needs inspection before repair.', [('The values must be rounded','Rounding cannot remove a text unit suffix.'),('pandas cannot convert numeric text','It converts strings such as "20".'),('The whole dataset must be deleted','Inspect the problematic value; the error does not justify deleting all data.')],'traceback'),
 q('What does this fill operation do?','s = pd.Series([20, None, 24, 80])\nfilled = s.fillna(s.median())','It inserts 24 for the missing entry and retains 80','The known values are 20, 24 and 80; the median is 24. fillna changes only missing entries.', [('It replaces 80 with 24','An extreme recorded value is not a missing value.'),('It recovers the true missing measurement','The fill is an estimate. It is never a recovered observation.'),('It fills the gap with zero','The supplied fill is the median, not zero.')]),
 q('Which output answers the question?','Question: Do mean target values differ by equipment?','A labelled chart of groupby("equipment_id")["target"].mean()','Grouped means compare the requested equipment groups.', [('One histogram of all targets','A pooled histogram describes a distribution without comparing group means.'),('The total row count alone','A count does not compare target means.'),('A chart with no labels','Without groups and units, the comparison cannot be interpreted.')],'judgement')],
 8:[
 q('What shape does X need here?','features = ["load_pct", "ambient_c"]\nX = train[features]\ny = train["target"]','One row per training observation and two feature columns','The two named features form a table; y has a target for each same row.', [('Two rows regardless of dataset size','Two is the feature count. The observation count is the number of rows.'),('A column containing the target only','The target is y. It is never a predictor.'),('One unrelated row for each target','Features and targets must refer to matching observations.')]),
 q('Why should prediction use new[features]?','model.fit(train[features], train["target"])','It keeps the same feature names and order as training','Names and order preserve the meaning of each model input.', [('It trains the model again','predict uses the fitted model; it does not fit it.'),('It supplies the new true target','Feature inputs must not contain the answer.'),('It guarantees accurate predictions','Consistent inputs are necessary but do not guarantee accuracy.')],'diagnosis'),
 q('What should you check first?','model.fit(X, y)\nValueError: Found input variables with inconsistent numbers of samples','Whether X and y were selected from the same rows','Separate filtering can leave different observation counts or mismatched rows.', [('Increase tree depth','Model complexity does not repair mismatched inputs.'),('Delete target values at random','This breaks pairing and loses valid data.'),('Round all columns','Rounding does not change the number of observations.')],'traceback'),
 q('What are MAE and RMSE?','actual = [10, 20]\npredicted = [12, 16]','MAE 3; RMSE approximately 3.1623','Absolute errors are 2 and 4; squared errors are 4 and 16.', [('MAE -1; RMSE 1','MAE uses absolute errors, so signed cancellation is wrong.'),('Both are 6','Six is the total absolute error. The mean divides it by the count.'),('Both are percentages','These errors use the target unit.')]),
 q('Where should the imputer learn its median?','Training, validation and final-test partitions are already separate.','Training features only','The fitted fill must be reused on evaluation data without learning from them.', [('The combined file','That uses evaluation information in preprocessing.'),('Validation targets','Targets cannot supply predictor fill values.'),('Each new prediction row independently','This changes preprocessing at prediction time.')],'judgement')],
 9:[
 q('How many false negatives are present?','actual    = [1, 1, 0, 0]\npredicted = [1, 0, 1, 0]','1','Only the second row needs a warning but receives none.', [('2','There are two errors, but only one is a false negative.'),('0','The second row is a missed warning.'),('4','Every row is not an error.')]),
 q('Why is high accuracy insufficient here?','Only 2% of observations need a warning. A model always predicts 0.','It misses every actual warning','Predicting the majority can give 98% accuracy while recall is zero.', [('It detects all warnings','It predicts no warnings at all.'),('It must have perfect recall','Recall counts detected positives, not correct negatives.'),('The dataset has no positive observations','Two percent are positives.')],'diagnosis'),
 q('How should this assignment avoid the error?','precision = tp / (tp + fp)\nZeroDivisionError: division by zero','Return 0 when tp + fp is zero, as specified','The published convention handles the no-predicted-warning case.', [('Invent one true positive','That changes the evidence.'),('Delete the entire dataset','A zero denominator needs a convention, not deletion.'),('Use the target unit as denominator','Units are not observation counts.')],'traceback'),
 q('What is the cost under this rule?','Missed warning costs 5; false alarm costs 1.\nfn = 2; fp = 3','13','5 times 2 plus 3 is 13.', [('5','This ignores the supplied error counts.'),('25','The costs are not both five.'),('6','Multiplying the two counts is not the stated rule.')]),
 q('What can lowering the threshold change?','Probabilities stay fixed; threshold falls from 0.5 to 0.3.','More observations can be classified as warnings','The decision rule changes; actual labels are needed to assess its errors.', [('It retrains the model automatically','Thresholding does not fit model parameters.'),('It guarantees fewer false alarms','Raising more warnings can increase false alarms.'),('It changes the actual labels','The reference outcomes stay fixed.')],'judgement')],
 10:[
 q('Why keep an equipment ID in only one partition?','The intended deployment is on previously unseen equipment.','To avoid evaluating on equipment patterns already seen in training','Repeated observations from one source can make evaluation too optimistic.', [('To make every partition equally large','Group separation does not guarantee equal counts.'),('To delete repeated valid observations','Repeated observations can be valid and remain in their group.'),('To use the target as a group label','Equipment identity defines this split. The answer plays no part.')]),
 q('What is wrong with this preparation?','median = all_rows["ambient_c"].median()\n# split into training and validation afterwards','It uses validation information when learning a fill value','Split first and fit preprocessing on training only.', [('A median is never allowed','Training-only median imputation is allowed when justified.'),('pandas cannot calculate medians','It can; the problem is which rows it uses.'),('It guarantees underfitting','The direct problem is information leakage.')],'diagnosis'),
 q('Why might prediction still fail with missing inputs?','A pipeline contains only a regression model.\nValueError: Input X contains NaN.','The pipeline needs appropriate missing-feature preparation','Include the trained imputer before the model and fit it on training data.', [('The final-test target must be added to X','That would leak the answer.'),('The warning should be ignored','Ignoring an error does not supply usable inputs.'),('All values should become zero','Zero filling needs a justified policy and may distort data.')],'traceback'),
 q('What does this output show?','Training median = 22.\nValidation values [None, 40] become [22, 40].','The training fill was reused on validation','Validation 40 did not determine a separate fill.', [('The validation median was fitted','The given rule uses the training median.'),('The missing measurement was recovered','It is an estimate.'),('Every value was changed','The recorded 40 remains unchanged.')]),
 q('What should be reported for several validation folds?','Errors vary noticeably across folds.','The mean, variation and any important differences between folds','The best fold alone hides unstable performance.', [('Only the best fold','This cherry-picks the evaluation.'),('Only the training score','That does not describe held-out folds.'),('A claim of guaranteed future performance','Finite validation evidence cannot guarantee future errors.')],'judgement')],
 11:[
 q('Which values are produced?','load_pct = 40; ambient_c = 25\nload_fraction = load_pct / 100\ninteraction = load_pct * ambient_c','0.4 and 1000','Division converts percent to a fraction; multiplication creates the interaction.', [('40 and 65','The first needs division and the second multiplication.'),('4000 and 1.6','These use different operations.'),('0.4 and 65','An interaction here is a product. A sum would be a different feature.')]),
 q('Why is this feature invalid for prediction?','new_feature = future_target / load_pct','It uses the answer that is unavailable at prediction time','A predictor must be obtainable before the target is known.', [('Ratios are always invalid','Ratios of available inputs can be useful.'),('It has a short name','Naming is not the leakage issue.'),('pandas cannot divide columns','It can perform column arithmetic.')],'diagnosis'),
 q('What does this error suggest?','valid["interaction"]\nKeyError: \'interaction\'','The column has not been created under that name in valid','Apply the same named feature preparation to training and validation.', [('Fit on validation targets','That leaks evaluation answers.'),('The model has too many rows','This error concerns a missing key or label.'),('Round the validation data','Rounding does not create the column.')],'traceback'),
 q('What is the improvement?','base_mae = 3.0; extended_mae = 2.5\nimprovement = base_mae - extended_mae','0.5 in the target unit','The extended model reduces mean absolute error by 0.5.', [('0.5 percent in every case','MAE uses the target unit. It is not an automatic percentage.'),('-0.5','That reverses the stated subtraction.'),('A guarantee every prediction improved','An average improvement does not guarantee each row improved.')]),
 q('What makes the comparison meaningful?','Compare base features with base features plus an interaction.','Use the same training and validation rows and model protocol','Changing only the feature set makes the difference interpretable.', [('Choose a different easy validation set','That confounds the comparison.'),('Use final-test scores to keep trying features','That turns the final test into selection data.'),('Always prefer the larger feature set','More features can fail to improve generalisation.')],'judgement')],
 12:[
 q('Which candidate meets both constraints?','Limits: MAE <= 3 and latency <= 10 ms.\nsimple: MAE 3, latency 2\ncomplex: MAE 1, latency 20','simple','It satisfies both inclusive limits.', [('complex','Its latency fails the requirement.'),('Both','complex fails the latency limit.'),('Neither','simple meets the limits, including equality on MAE.')]),
 q('What is wrong with choosing the lowest error before filtering?','One very accurate candidate exceeds the permitted latency.','The chosen candidate may be ineligible','Check every constraint before ranking eligible candidates.', [('Sorting cannot be used','Sorting is useful after eligibility filtering.'),('Latency and error must be added','They have different meanings and the policy does not add them.'),('All constraints should be dropped','That changes the requirements.')],'diagnosis'),
 q('What check prevents this error?','winner = eligible.iloc[0]["name"]\nIndexError: single positional indexer is out-of-bounds','Check eligible.empty and return None if no rows remain','There is no first row in an empty table.', [('Use iloc[1] instead','An empty table has no second row either.'),('Always pick the original first candidate','That can choose an ineligible model.'),('Delete the latency column','Removing evidence does not satisfy the constraints.')],'traceback'),
 q('Which name wins the published tie-break?','Both candidates have MAE 2 and latency 3 ms.\nNames: beta, alpha\nSort by error, latency, then name.','alpha','With equal numerical criteria, alphabetical name order decides.', [('beta','That is not the alphabetical first name.'),('Whichever appeared last','Input order is not the stated tie-break.'),('None','Both are eligible and the tie-break resolves the choice.')]),
 q('Which data should guide model selection?','The final test is reserved for the fixed choice.','Validation results under a consistent protocol','The final test should remain independent of repeated choices.', [('Final-test results after every trial','Repeated selection on those results uses up the final test.'),('The nicest-looking training plot','Appearance does not establish held-out performance.'),('The largest number of parameters','Complexity alone does not establish quality.')],'judgement')]
 }
 for week,questions in banks.items():
  quiz[week]['q']=questions
  quiz[week]['intro']='Five questions on the pandas workflow and engineering decisions taught this week. Read each example before choosing one answer.'
 return quiz
